export function getBScSem6UnitKnowledge(subjectName: string, unitNumber: number): TopicKnowledge | null {
  const s = subjectName.toLowerCase().trim();
  const key = `${s}:::u${unitNumber}`;
  if (bscSem6Knowledge[key]) {
    return bscSem6Knowledge[key];
  }
  // Fuzzy match on subject name
  for (const [k, v] of Object.entries(bscSem6Knowledge)) {
    const [subKey, uKey] = k.split(":::u");
    if (uKey === String(unitNumber) && (s.includes(subKey) || subKey.includes(s))) {
      return v;
    }
  }
  return null;
}
